const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Local release signing. `android/` is generated by `expo prebuild`, so the signing config is
 * injected here instead of edited by hand.
 *
 * The upload key never lives in the repo: put these in `~/.gradle/gradle.properties`
 * (or pass them with -P):
 *   SPORTS247_UPLOAD_STORE_FILE=C:/keys/sports247-upload.jks
 *   SPORTS247_UPLOAD_STORE_PASSWORD=…
 *   SPORTS247_UPLOAD_KEY_ALIAS=upload
 *   SPORTS247_UPLOAD_KEY_PASSWORD=…
 * Without them a local release build falls back to the debug key (fine for testing, rejected by
 * Google Play). EAS Build ignores this and signs with the credentials it manages.
 */
module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes('SPORTS247_UPLOAD_STORE_FILE')) return cfg;

    gradle = gradle.replace(/signingConfigs \{\n(\s+)debug \{/, (_m, indent) =>
      [
        'signingConfigs {',
        `${indent}release {`,
        `${indent}    if (project.hasProperty('SPORTS247_UPLOAD_STORE_FILE')) {`,
        `${indent}        storeFile file(SPORTS247_UPLOAD_STORE_FILE)`,
        `${indent}        storePassword SPORTS247_UPLOAD_STORE_PASSWORD`,
        `${indent}        keyAlias SPORTS247_UPLOAD_KEY_ALIAS`,
        `${indent}        keyPassword SPORTS247_UPLOAD_KEY_PASSWORD`,
        `${indent}    }`,
        `${indent}}`,
        `${indent}debug {`,
      ].join('\n'),
    );
    gradle = gradle.replace(
      /(release \{\n\s+\/\/ Caution![^\n]*\n\s+\/\/ see[^\n]*\n\s+)signingConfig signingConfigs\.debug/,
      "$1signingConfig project.hasProperty('SPORTS247_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    );
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
